import { cookies, headers } from 'next/headers'

/**
 * Parse the Accept-Language header and return the most preferred language.
 * The header format is: "en-US,en;q=0.9,fr;q=0.8" — entries are sorted by
 * their quality value (q), with absent q-values defaulting to 1.
 */
function getPreferredLanguage(acceptLanguage: string): string {
  if (!acceptLanguage) {
    return 'en'
  }

  const entries = acceptLanguage
    .split(',')
    .map((part) => {
      const [lang, ...params] = part.trim().split(';')
      const qParam = params.find((p) => p.trim().startsWith('q='))
      const q = qParam ? Number.parseFloat(qParam.split('=')[1]) : 1
      return { lang: lang.trim(), q: Number.isNaN(q) ? 1 : q }
    })
    .filter((entry) => entry.lang.length > 0)
    .sort((a, b) => b.q - a.q)

  return entries[0]?.lang ?? 'en'
}

export default async function PreferencesDisplay() {
  const cookieStore = await cookies()
  const theme = cookieStore.get('theme')?.value ?? 'light'

  const headerStore = await headers()
  const preferredLanguage = getPreferredLanguage(
    headerStore.get('accept-language') ?? '',
  )

  return (
    <div>
      <p>Current theme: {theme}</p>
      <p>Preferred language: {preferredLanguage}</p>
    </div>
  )
}

